SELECT CASE WHEN o.discount >= 0.39 THEN 'high' WHEN o.discount >= 0.19 THEN 'mid' ELSE 'low' END AS discount_bucket, COUNT(oi.unit_price) AS unit_price_count, ROUND(AVG(oi.unit_price), 2) AS avg_unit_price FROM order_items oi JOIN orders o ON o.id = oi.order_id FULL OUTER JOIN products p ON p.id = oi.product_id GROUP BY CASE WHEN o.discount >= 0.39 THEN 'high' WHEN o.discount >= 0.19 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(oi.unit_price), 2) >= 51 ORDER BY avg_unit_price DESC;
